package com.tripmateai.service.impl;
import com.tripmateai.dto.request.trip.*; import com.tripmateai.dto.response.trip.*; import com.tripmateai.entity.*; import com.tripmateai.exception.*; import com.tripmateai.mapper.TripMapper; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.TripService; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.HashSet;
@Service @RequiredArgsConstructor @Transactional @SuppressWarnings("all") public class TripServiceImpl implements TripService { private final TripRepository trips; private final DestinationRepository destinations; private final SavedTripRepository saved; private User current(){var p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(p instanceof UserPrincipal principal))throw new UnauthorizedException("Authentication required");return principal.user();} private Trip own(Long id){return trips.findByIdAndUser(id,current()).orElseThrow(()->{if(trips.existsById(id))return new UnauthorizedException("You do not have access to this trip");return new ResourceNotFoundException("Trip not found");});} private Pageable page(int p,int s,String sort){var property="startDate";var dir=Sort.Direction.DESC;if("oldest".equalsIgnoreCase(sort)){property="createdAt";dir=Sort.Direction.ASC;}else if("newest".equalsIgnoreCase(sort))property="createdAt";return PageRequest.of(Math.max(p,0),Math.min(Math.max(s,1),100),dir,property);} private void dates(LocalDate start,LocalDate end){if(end.isBefore(start))throw new BadRequestException("End date cannot be before start date");}
 public TripResponse createTrip(CreateTripRequest r){dates(r.startDate(),r.endDate());var d=destinations.findById(r.destinationId()).orElseThrow(()->new ResourceNotFoundException("Destination not found"));var t=new Trip();t.setUser(current());t.setDestination(d);t.setTripName(r.tripName());t.setStartDate(r.startDate());t.setEndDate(r.endDate());t.setBudget(r.budget());t.setNumberOfTravelers(r.numberOfTravelers());t.setPreferences(r.preferences()==null?new HashSet<>():new HashSet<>(r.preferences()));return TripMapper.toResponse(trips.save(t));}
 @Transactional(readOnly=true) public Page<TripSummaryResponse> getMyTrips(int p,int s,String sort){return trips.findByUser(current(),page(p,s,sort)).map(TripMapper::toSummary);} @Transactional(readOnly=true) public TripResponse getTripById(Long id){return TripMapper.toResponse(own(id));}
 public TripResponse updateTrip(Long id,UpdateTripRequest r){dates(r.startDate(),r.endDate());var t=own(id);t.setTripName(r.tripName());t.setStartDate(r.startDate());t.setEndDate(r.endDate());t.setBudget(r.budget());t.setNumberOfTravelers(r.numberOfTravelers());return TripMapper.toResponse(trips.save(t));} public void deleteTrip(Long id){trips.delete(own(id));}
 public TripResponse duplicateTrip(Long id,DuplicateTripRequest r){var o=own(id);var n=new Trip();n.setUser(current());n.setDestination(o.getDestination());n.setTripName(r.tripName());n.setStartDate(o.getStartDate());n.setEndDate(o.getEndDate());n.setBudget(o.getBudget());n.setNumberOfTravelers(o.getNumberOfTravelers());n.setTripStatus(o.getTripStatus());n.setPreferences(new HashSet<>(o.getPreferences()));return TripMapper.toResponse(trips.save(n));}
 public void saveTrip(Long id){var t=trips.findById(id).orElseThrow(()->new ResourceNotFoundException("Trip not found"));var u=current();if(saved.existsByUserAndTrip(u,t))throw new BadRequestException("Trip is already saved");var record=new SavedTrip();record.setUser(u);record.setTrip(t);saved.save(record);} public void unsaveTrip(Long id){var t=trips.findById(id).orElseThrow(()->new ResourceNotFoundException("Trip not found"));saved.delete(saved.findByUserAndTrip(current(),t).orElseThrow(()->new ResourceNotFoundException("Saved trip not found")));}
 @Transactional(readOnly=true) public Page<TripSummaryResponse> getSavedTrips(int p,int s){return saved.findByUser(current(),page(p,s,"newest")).map(x->TripMapper.toSummary(x.getTrip()));} @Transactional(readOnly=true) public Page<TripSummaryResponse> getPreviousTrips(int p,int s){return trips.findByUserAndEndDateBefore(current(),LocalDate.now(),page(p,s,"startDate")).map(TripMapper::toSummary);} }
